type Page='overview'|'activity'|'plan'|'accounts'|'statistics'|'settings'|'goals';
type Panel={kind:'explain';view:'available'|'daily'|'weekly'|'cash'}|{kind:'configure'}|{kind:'fund'}|{kind:'bucket';bucket?:Bucket}|{kind:'move'}|{kind:'payment';occurrence:Occurrence}|{kind:'assign'};
const money=(n:number,currency='EUR',locale='en-IE')=>new Intl.NumberFormat(locale,{style:'currency',currency}).format(n/100);
// "Weekly", or "Every 2 weeks" when the plan skips periods.
const repeatUnits:Record<string,[string,string]>={daily:['Daily','days'],weekly:['Weekly','weeks'],monthly:['Monthly','months'],yearly:['Yearly','years']};
const repeatLabel=(frequency:string,interval:number,tr:(key:string)=>string)=>{const [single,plural]=repeatUnits[frequency]||[frequency,frequency];return interval>1?`${tr("Every")} ${interval} ${tr(plural)}`:tr(single);};
const dateLabel=(date:string,locale='en-GB')=>new Date(date+'T12:00:00Z').toLocaleDateString(locale,{day:'numeric',month:'short',timeZone:'UTC'});
const nav:[Page,string,string][]=[['overview','Overview','home'],['activity','Activity','activity'],['plan','Plan','plan'],['statistics','Insights','insights'],['accounts','Accounts','accounts'],['settings','Settings','settings']];
function initialPage():Page { if(typeof window==='undefined')return 'overview';const value=new URL(window.location.href).searchParams.get('view');const candidate=value;return candidate&&[...nav.map(n=>n[0]),'goals'].includes(candidate)?candidate as Page:'overview'; }
function Icon({name}:{name:string}){const paths:Record<string,string>={refresh:'M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 13 3l1 3M4 12l1 3a8 8 0 0 0 13 3',home:'M3 10 12 3l9 7v10H3V10Zm6 10v-7h6v7',activity:'M3 12h4l3-8 4 16 3-8h4',plan:'M5 4h14v17H5V4Zm3-2v4m8-4v4M8 10h8M8 14h8M8 18h4',insights:'M3 19V5m0 14h18M6 15l5-5 4 3 6-8',accounts:'M3 7h18v13H3V7Zm0 0 14-4v4M16 12h5v4h-5v-4',settings:'M4 7h16M4 17h16M8 4v6m8 4v6',plus:'M12 4v16M4 12h16',arrow:'M4 12h16m-6-6 6 6-6 6',check:'m5 12 4 4L19 6',goals:'M12 3l8 9-8 9-8-9 8-9Z',search:'M11 18a7 7 0 1 0 0-14 7 7 0 0 0 0 14Zm9 2-4-4',chevron:'m6 9 6 6 6-6',alert:'M12 9v4m0 4h.01M10.3 3.9 2.6 17.5A2 2 0 0 0 4.3 20.5h15.4a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0Z'};return <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={paths[name]||paths.plan}/></svg>;}

function AppearanceSettings({theme,busy,onChange}:{theme:UITheme;busy:boolean;onChange:(theme:UITheme)=>void}){
 const { t: tr } = useTranslation();

 return <section className="v3-card v3-appearance"><div className="v3-section-head"><div><span className="v3-eyebrow">{tr("MAKE IT YOURS")}</span><h2>{tr("Appearance")}</h2></div></div><p>{tr("Choose a look for your workspace. Your preference is saved to your account.")}</p><div className="v3-theme-options" role="group" aria-label={tr("Workspace theme")}>{uiThemes.map(option=><button key={option.id} className="v3-theme-option" aria-pressed={theme===option.id} disabled={busy} onClick={()=>onChange(option.id)}><span className="v3-theme-preview" aria-hidden="true" style={{background:option.canvas}}><span style={{background:option.surface}}/><i style={{background:option.accent}}/><b style={{background:option.surface}}/></span><span className="v3-theme-title"><strong>{option.name}</strong>{theme===option.id&&<Icon name="check"/>}</span><small>{tr(option.description)}</small></button>)}</div></section>;
}

function DataExportCard(){
 const { t: tr } = useTranslation();

 return <section className="v3-card v3-data-export"><div className="v3-section-head"><div><span className="v3-eyebrow">{tr("YOUR DATA")}</span><h2>{tr("Export your data")}</h2></div></div>
  <p>{tr("Download your current Remaivo data in one JSON file. It includes accounts, activity, plans, goals, settings and history.")}</p>
  <div className="v3-data-export-actions"><a className="v3-primary" href="/api/finance?view=export">{tr("Download JSON export")}</a><span>{tr("This file contains private financial information. Store it somewhere safe.")}</span></div>
 </section>;
}
function RemaivoWorkspace(props:{displayName:string;email:string;signOutHref:string}){
 const { t: tr, locale, language } = useTranslation();

 const [data,setData]=useState<Snapshot|null>(null);const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [revision,setRevision]=useState(0);const [accountsView,setAccountsView]=useState<'balances'|'report'>('balances');const [page,setPage]=useState<Page>(initialPage);const [panel,setPanel]=useState<Panel|null>(null);const [modal,setModal]=useState<ModalName>(null);const [edit,setEdit]=useState<EditTarget|null>(null);const [goalEntry,setGoalEntry]=useState<Goal|null>(null);const [valuation,setValuation]=useState<Account|null>(null);const [notice,setNotice]=useState('');
 const [archiveOpen,setArchiveOpen]=useState(false);
 const [planPromptHidden,setPlanPromptHidden]=useState(()=>{try{return localStorage.getItem('remaivo:plan-prompt')==='hidden';}catch{return false;}});
 const { setLanguage } = useTranslation();
 useEffect(()=>{if(data?.profile) setLanguage(normalizeLanguage(data.profile.ui_language));},[data?.profile?.ui_language, data?.profile, setLanguage]);
 const theme=normalizeUITheme(data?.profile?.ui_theme);
 useEffect(()=>{document.documentElement.dataset.theme=theme;return()=>{delete document.documentElement.dataset.theme;};},[theme]);
 const loadingRef=useRef(false);
 const busyRef=useRef(false);
 const mutationRef=useRef(0);
 const dataRef=useRef<Snapshot|null>(null);
 const fingerprintRef=useRef<string|null>(null);
 const [refreshPolicy]=useState(()=>new FinanceRefreshPolicy(Date.now()));
 const [refreshing,setRefreshing]=useState(false);
 const dialogOpen=Boolean(panel||modal||edit||goalEntry||valuation||archiveOpen);
 const dialogOpenRef=useRef(false);
 useEffect(()=>{dialogOpenRef.current=dialogOpen;},[dialogOpen]);
 useEffect(()=>{
  if(!dialogOpen)return;
  const previousOverflow=document.body.style.overflow;
  const previousFocus=document.activeElement as HTMLElement|null;
  document.body.style.overflow='hidden';
  const dialog=document.querySelector<HTMLElement>('.dialog-frame[role="dialog"]');
  const focusable=()=>Array.from(dialog?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled):not([type="hidden"]),select:not(:disabled),a[href]')||[]).filter(el=>el.getClientRects().length);
  if(dialog)focusable()[0]?.focus();
  const keydown=(event:KeyboardEvent)=>{
   if(!dialog)return;
   if(event.key==='Escape'){setModal(null);setEdit(null);setGoalEntry(null);setValuation(null);setPanel(null);setArchiveOpen(false);}
   if(event.key==='Tab'){const nodes=focusable();const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
  };
  document.addEventListener('keydown',keydown);
  return()=>{document.body.style.overflow=previousOverflow;document.removeEventListener('keydown',keydown);if(dialog)previousFocus?.focus();};
 },[dialogOpen]);
 useEffect(()=>{
  const focusSearch=(event:KeyboardEvent)=>{
   if(dialogOpen)return;
   if(event.key!=='/'||event.metaKey||event.ctrlKey||event.altKey)return;
   const target=event.target as HTMLElement|null;
   if(target&&(target.isContentEditable||['INPUT','TEXTAREA','SELECT'].includes(target.tagName)))return;
   const input=document.querySelector<HTMLInputElement>('.v3-global-search input');
   if(input&&input.getClientRects().length){event.preventDefault();input.focus();}
  };
  document.addEventListener('keydown',focusSearch);
  return()=>document.removeEventListener('keydown',focusSearch);
 },[dialogOpen]);
 useEffect(()=>{
  const restorePage=()=>setPage(initialPage());
  window.addEventListener('popstate',restorePage);
  return()=>window.removeEventListener('popstate',restorePage);
 },[]);
 const load=useCallback(async(force=true)=>{
  if(loadingRef.current||busyRef.current||(!force&&dialogOpenRef.current))return;
  const now=Date.now();
  if(!force&&!refreshPolicy.due(now,document.visibilityState==='visible',financialToday(dataRef.current?.profile?.timezone||'UTC')))return;
  refreshPolicy.attempted(now);
  loadingRef.current=true;
  setRefreshing(true);
  const mutation=mutationRef.current;
  const controller=new AbortController();
  const timeout=setTimeout(()=>controller.abort(),20000);
  try{
   const r=await fetch('/api/finance',{signal:controller.signal});
   const next=await r.json() as Snapshot;
   if(!r.ok)throw new Error(next.error||'Unable to load your money.');
   // Reads started before a save cannot overwrite that save's authoritative result.
   if(mutation!==mutationRef.current)return;
   const result=snapshotChanged(fingerprintRef.current,next);
   if(force||result.changed)invalidateFinancePageCache();
   if(result.changed)setData(next);
   dataRef.current=next;fingerprintRef.current=result.fingerprint;
   refreshPolicy.succeeded(Date.now(),next.today);
   setRevision(x=>x+1);setError('');
  }catch(e){if(mutation===mutationRef.current)setError(controller.signal.aborted?'Your workspace is taking too long to load. Please try again.':e instanceof Error?e.message:tr("Unable to connect."));}
  finally{clearTimeout(timeout);loadingRef.current=false;setRefreshing(false);}
 },[refreshPolicy,tr]);
 useEffect(()=>{
  queueMicrotask(()=>{void load(false);});
  const timer=setInterval(()=>{void load(false);},30000);
  const activity=()=>{refreshPolicy.activity(Date.now());};
  const visible=()=>{if(document.visibilityState==='visible'){activity();void load(false);}};
  const online=()=>{if(document.visibilityState==='visible'){activity();void load(false);}};
  document.addEventListener('pointerdown',activity,{passive:true});
  document.addEventListener('keydown',activity);
  document.addEventListener('scroll',activity,{passive:true,capture:true});
  document.addEventListener('visibilitychange',visible);
  window.addEventListener('online',online);
  return()=>{clearInterval(timer);document.removeEventListener('pointerdown',activity);document.removeEventListener('keydown',activity);document.removeEventListener('scroll',activity,true);document.removeEventListener('visibilitychange',visible);window.removeEventListener('online',online);};
 },[load,refreshPolicy]);
 function navigate(next:Page){setPage(next);window.scrollTo({top:0,behavior:'instant'});const url=new URL(window.location.href);url.searchParams.set('view',next);window.history.replaceState({},'',url);}
 function searchActivity(event:FormEvent<HTMLFormElement>){
  event.preventDefault();
  const query=String(new FormData(event.currentTarget).get('q')||'').trim();
  const url=new URL(window.location.href);
  if(query)url.searchParams.set('description',query);else url.searchParams.delete('description');
  url.searchParams.set('view','activity');
  window.history.pushState({},'',url);
  setPage('activity');
  window.scrollTo({top:0,behavior:'instant'});
  // An already-open Activity page restores its filters from the URL on popstate.
  window.dispatchEvent(new PopStateEvent('popstate'));
 }
 async function save(action:string,payload:Record<string,unknown>){if(busyRef.current)return false;busyRef.current=true;mutationRef.current+=1;setBusy(true);setError('');try{const r=await fetch('/api/finance',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action,payload})});const next=await r.json() as Snapshot;if(!r.ok)throw new Error(next.error||'Unable to save.');invalidateFinancePageCache();dataRef.current=next;fingerprintRef.current=JSON.stringify(next);refreshPolicy.succeeded(Date.now(),next.today);setData(next);setRevision(x=>x+1);setNotice(tr("Saved"));setTimeout(()=>setNotice(''),2400);return true;}catch(e){setError(e instanceof Error?e.message:tr("Unable to save."));return false;}finally{busyRef.current=false;setBusy(false);}}
 const saveModal=async(a:string,p:Record<string,unknown>)=>{if(await save(a,p)){setModal(null);setEdit(null);}};
 if(!data)return <main className="v3-loading"><span className="v3-monogram">{tr("R")}</span><h1>{tr("Your money, in view.")}</h1><p>{tr(error)||'Opening your financial workspace…'}</p>{error&&<button onClick={()=>void load()}>{tr("Try again")}</button>}</main>;
 if(data.needsSetup)return <Onboarding displayName={props.displayName} busy={busy} error={error} onComplete={payload=>save('setup',payload)}/>;
 if(!data.v3||!data.profile)return <main className="v3-loading"><h1>{tr("Your plan is being prepared")}</h1><p>{tr(error)||'Refresh to open your workspace.'}</p><button onClick={()=>void load()}>{tr("Refresh")}</button></main>;
 const v3=data.v3;const r=v3.result;const currency=data.profile.currency;const m=(n:number)=>money(n,currency, locale);const accounts=(data.accounts||[]).filter(a=>!a.archived);const categories=data.categories||[];const transactions=data.transactions||[];const accountById=Object.fromEntries((data.accounts||[]).map(a=>[a.id,a]));const categoryById=Object.fromEntries(categories.map(c=>[c.id,c]));
 const investmentMetrics=Object.fromEntries(accounts.filter(a=>a.type==='investment').map(a=>[a.id,calculateInvestmentValue({accountId:a.id,rawInvested:a.balance_cents,transactions,snapshots:data.investmentSnapshots||[]})]));
 const rawInvested=accounts.filter(a=>a.type==='investment').reduce((s,a)=>s+a.balance_cents,0);const invested=Object.values(investmentMetrics).reduce((s,x)=>s+x.estimatedCurrentValue,0);const savings=accounts.filter(a=>a.type==='savings').reduce((s,a)=>s+a.balance_cents,0);
 const context:Context={accounts,categories,transactions,recurring:data.recurring||[],installmentPlans:data.installmentPlans||[],installmentPayments:data.installmentPayments||[],goals:data.goals||[],goalEntries:data.goalEntries||[],investmentSnapshots:data.investmentSnapshots||[],investmentMetrics,profile:data.profile,currency,accountById,categoryById,spendable:r.spendable,savings,rawInvested,invested,investmentMovement:invested-rawInvested,investmentMovementPercent:rawInvested?(invested-rawInvested)/rawInvested*100:null,totalBalance:accounts.filter(a=>a.type!=='investment').reduce((s,a)=>s+a.balance_cents,0)+invested,outstandingInstallments:(data.installmentPlans||[]).reduce((s,p)=>s+p.total_cents-p.paid_cents,0),sparePot:(data.spareEvents||[]).reduce((s,e)=>s+e.multiplied_cents,0),today:data.today,adaptivePlan:v3?.config.allocation==='adaptive',planning:data.profile?.planning_enabled!==0};
 const planning=data.profile?.planning_enabled!==0;
 const enablePlanning=async()=>{if(await save('updatePlanning',{enabled:true})&&v3.config.target===0)setPanel({kind:'configure'});};
 const hidePlanPrompt=()=>{setPlanPromptHidden(true);try{localStorage.setItem('remaivo:plan-prompt','hidden');}catch{/* the card simply returns next visit */}};
 const navItems=nav.map(n=>n[0]==='plan'&&!planning?['plan','Scheduled','plan'] as [Page,string,string]:n);
 const upcoming=v3.occurrences.filter(o=>['upcoming','partial'].includes(o.status));const deficits=planning?r.buckets.filter(b=>b.deficit>0):[];const title=navItems.find(n=>n[0]===page)?.[1]||({settings:tr("Settings"),statistics:tr("Insights"),goals:tr("Savings & investing")} as Record<string,string>)[page];
 const allocationSegments=[{name:tr("Spent"),amount:r.totalSpent,color:'var(--pro-chart-strong)'},{name:tr("Protected"),amount:r.protectedRemaining,color:'var(--theme-chart-secondary)'},{name:tr("Everyday"),amount:Math.max(0,r.available),color:'var(--theme-accent)'}];
 const positionSegments=[{name:tr("Spending accounts"),amount:r.spendable,color:'var(--theme-accent)'},{name:tr("Savings"),amount:savings,color:'var(--pro-chart-positive)'},{name:tr("Investments"),amount:invested,color:'var(--pro-chart-strong)'}];
 const navButton=([key,label,icon]:[Page,string,string])=><button key={key} className={`${page===key?'active':''}${key==='settings'?' v3-settings-nav':''}`} aria-current={page===key?'page':undefined} aria-label={key==='settings'?tr("Settings"):undefined} title={tr(label)} onClick={()=>navigate(key)}><Icon name={icon}/><span className={key==='settings'?'v3-settings-label':'v3-nav-label'}>{tr(label)}</span>{key==='plan'&&deficits.length>0&&<span className="v3-nav-badge" aria-label={`${deficits.length} ${deficits.length===1?'bucket needs':'buckets need'} cover`}>{deficits.length}</span>}{page===key&&<span className="v3-nav-mark"/>}</button>;
 return <div className="v3-app" data-theme={theme}><aside className="v3-sidebar"><Link className="v3-brand" href="/" onClick={e=>{e.preventDefault();navigate('overview');}}><span className="v3-monogram">{tr("R")}</span><span className="v3-brand-text">{tr("Remaivo")}<small>{tr("Personal finance")}</small></span></Link><nav aria-label={tr("Main navigation")}>{navItems.filter(n=>n[0]!=='settings').map(navButton)}<div className="v3-space-label">{tr("Save & invest")}</div><button className={`v3-goals-nav ${page==='goals'?'active':''}`} aria-current={page==='goals'?'page':undefined} title={tr("Savings & investing")} onClick={()=>navigate('goals')}><Icon name="goals"/><span className="v3-nav-label">{tr("Savings & investing")}</span>{page==='goals'&&<span className="v3-nav-mark"/>}</button><div className="v3-space-label">{tr("Preferences")}</div>{navItems.filter(n=>n[0]==='settings').map(navButton)}</nav><div className="v3-sidebar-bottom"><div className="v3-profile"><span>{props.displayName.slice(0,1)}</span><div><strong>{props.displayName}</strong><small>{props.email}</small></div><a href={props.signOutHref}>{tr("Sign out")}</a></div></div></aside>
 <div className="v3-workspace"><header className="v3-topbar"><nav className="v3-breadcrumb" aria-label={tr("Breadcrumb")}>{tr("Remaivo")} <span>/</span> <span className="v3-breadcrumb-page">{tr(title)}</span></nav><span className="v3-mobile-brand" aria-hidden="true"><span className="v3-monogram">{tr("R")}</span>{tr("Remaivo")}</span><div className="v3-header-actions"><button className="v3-refresh" type="button" aria-label={tr("Refresh finances")} title={tr("Refresh finances")} disabled={busy||refreshing} onClick={()=>void load()}><Icon name="refresh"/></button><form className="v3-global-search" role="search" onSubmit={searchActivity}><Icon name="search"/><input key={page} name="q" type="search" placeholder={tr("Search transactions")} aria-label={tr("Search transactions")} defaultValue={page==='activity'&&typeof window!=='undefined'?new URL(window.location.href).searchParams.get('description')||'':''}/><kbd aria-hidden="true">/</kbd></form><button className="v3-primary" aria-label={tr("Add transaction")} onClick={()=>setModal("transaction")}><Icon name="plus"/><span className="v3-add-label">{tr("Add transaction")}</span></button></div></header>
 <div className="v3-content">
 <div className="v3-page-head"><h1>{tr(title)}</h1>{planning&&<div className="v3-period-bar"><button onClick={()=>setPanel({kind:'configure'})}><span className="v3-period-dot"/>{v3.config.name}<span className="v3-chevron" aria-hidden="true"><Icon name="chevron"/></span></button><span>{dateLabel(r.start, locale)} — {dateLabel(plusDays(r.end,-1), locale)}, {r.start.slice(0,4)}</span><span className="v3-period-mode">{v3.config.allocation==='adaptive'?tr("Adaptive"):v3.config.allocation==='weighted'?tr("Weighted"):tr("Even")}  {tr("pacing")}</span></div>}</div>
 {error&&<div className="v3-alert" role="alert"><span>{tr(error)}</span><button onClick={()=>setError('')} aria-label={tr("Dismiss error")}>×</button></div>}{notice&&<div className="v3-toast" role="status"><Icon name="check"/>{notice}</div>}
 {planning&&r.cashShortfall>0&&<div className="v3-alert warning">{tr("Your remaining allocations exceed spending-account cash by")} {m(r.cashShortfall)}. <button onClick={()=>setPanel({kind:'fund'})}>{tr("Review funding")}</button></div>}
 {page==='overview'&&<>{deficits.length>0&&<div className="v3-alert warning"><Icon name="alert"/><span>{deficits.map(b=>`${b.name} needs ${m(b.deficit)} of cover`).join(' · ')}</span><button onClick={()=>setPanel({kind:'move'})}>{tr("Move allocation")}</button></div>}
 {planning?<section className="v3-card v3-ov-hero"><div className="v3-hero"><div className="v3-hero-top"><span className="v3-eyebrow">{tr("Everyday money")}</span><button onClick={()=>setPanel({kind:'explain',view:'available'})} aria-label={tr("Explain everyday money")}>{tr("How it’s calculated")}</button></div><button className={`v3-hero-amount ${r.available<0?'negative':''}`} onClick={()=>setPanel({kind:'explain',view:'available'})}>{m(r.available)}</button><p>{r.available<0?'Your plan needs more funding or smaller allocations.':'Available after spending and protected allocations.'}</p><div className="v3-guidance"><button onClick={()=>setPanel({kind:'explain',view:'daily'})}><span>{tr("Today’s allowance")}</span><strong>{m(r.daily.remaining)}</strong><small>{m(r.daily.spent)}  {tr("everyday spending today")}</small></button><button onClick={()=>setPanel({kind:'explain',view:'weekly'})}><span>{tr("This week")}</span><strong>{m(r.weekly.remaining)}</strong><small>{dateLabel(r.weekStart, locale)} — {dateLabel(plusDays(r.weekEnd,-1), locale)}</small></button></div></div><SpendingChart start={r.start} end={r.end} today={data.today} target={r.target} spent={r.totalSpent} transactions={v3.transactions} currency={currency}/></section>:<MonthCard month={data.month!} currency={currency} onInsights={()=>navigate('statistics')}/>}
 <div className={planning||!planPromptHidden?'v3-two-columns':'v3-one-column'}><section className="v3-card v3-position"><div className="v3-section-head"><h2>{tr("Your position")}</h2><button onClick={()=>navigate('accounts')}>{tr("Accounts")} <Icon name="arrow"/></button></div><div className="v3-position-total"><span>{tr("Total recorded value")}</span><strong>{m(context.totalBalance)}</strong></div>{positionSegments.some(s=>s.amount>0)&&<div className="v3-position-bar" aria-hidden="true">{positionSegments.map(s=><span key={s.name} style={{flex:Math.max(0,s.amount),background:s.color}}/>)}</div>}<button className="v3-cash-line" onClick={()=>setPanel({kind:'explain',view:'cash'})}><i style={{background:positionSegments[0].color}}/><span>{tr("Spending accounts")}</span><strong>{m(r.spendable)}</strong></button><div className="v3-position-row"><i style={{background:positionSegments[1].color}}/><span>{tr("Savings")}</span><b>{m(savings)}</b></div><div className="v3-position-row"><i style={{background:positionSegments[2].color}}/><span>{tr("Investments")}</span>{context.investmentMovementPercent!==null&&Math.abs(context.investmentMovementPercent)>=0.005&&<em className={context.investmentMovement>=0?'v3-positive':'v3-negative'}>{context.investmentMovementPercent>0?'+':''}{context.investmentMovementPercent.toFixed(2)}%</em>}<b>{m(invested)}</b></div><p className="v3-note">{tr("Account balances show where money lives. Assignments show what it is for.")}</p></section>
 {planning?<section className="v3-card v3-allocation"><div className="v3-section-head"><div><span className="v3-eyebrow">{tr("This period")}</span><h2>{tr("Every euro has a place")}</h2></div><button onClick={()=>navigate('plan')}>{tr("Manage plan")} <Icon name="arrow"/></button></div><div className="v3-allocation-bar" role="img" aria-label={`Plan allocation: ${allocationSegments.map(s=>`${s.name} ${m(s.amount)}`).join(', ')}`}>{allocationSegments.map(s=><span key={s.name} style={{flex:Math.max(0,s.amount),background:s.color}}/>)}</div><div className="v3-allocation-legend">{allocationSegments.map(s=><div key={s.name}><span><i style={{background:s.color}}/>{s.name}</span>{r.funding>0&&<small>{Math.round(Math.max(0,s.amount)/r.funding*100)}%</small>}<strong>{m(s.amount)}</strong></div>)}<div className="v3-allocation-funded"><span><i/>{tr("Funded")}</span><strong>{m(r.funding)}</strong></div></div>{r.unfunded>0&&<p className="v3-note">{tr("Your")} {m(r.target)}  {tr("target has")} {m(r.unfunded)}  {tr("still to fund.")} <button onClick={()=>setPanel({kind:'fund'})}>{tr("Adjust funding")}</button></p>}</section>:!planPromptHidden&&<section className="v3-card v3-plan-prompt"><span className="v3-eyebrow">{tr("Spending plan")}</span><h2>{tr("Want a spending plan?")}</h2><p>{tr("Set a target for each period and Remaivo paces your everyday spending and holds money for upcoming bills.")}</p><div><button className="v3-primary" disabled={busy} onClick={()=>void enablePlanning()}>{tr("Set one up")}</button><button className="v3-secondary" onClick={hidePlanPrompt}>{tr("Not now")}</button></div></section>}</div>
 <div className="v3-two-columns"><section className="v3-card"><div className="v3-section-head"><h2>{tr("Coming up")}</h2><button onClick={()=>navigate('plan')}>{tr("All payments")} <Icon name="arrow"/></button></div><OccurrenceList items={upcoming.slice(0,5)} today={data.today} currency={currency} onOpen={o=>setPanel({kind:'payment',occurrence:o})}/></section><section className="v3-card"><div className="v3-section-head"><h2>{tr("Recent activity")}</h2><button onClick={()=>navigate('activity')}>{tr("View all")} <Icon name="arrow"/></button></div><div className="activity-list">{transactions.slice(0,5).map(t=><TransactionRow key={t.id} transaction={t} accountById={accountById} categoryById={categoryById} currency={currency} onEdit={()=>setEdit({kind:"transaction",record:t})}/>)}</div>{!transactions.length&&<Empty title={tr("A clear starting point")} text={tr("Your transactions will appear here as you record them.")}/>}</section></div>
 {planning&&<section className="v3-card v3-recent"><div className="v3-section-head"><h2>{tr("What changed")}</h2></div>{v3.events.slice(0,3).map(e=><div className="v3-event" key={e.id}><span className="v3-event-mark"><Icon name={e.kind==='payment'?'check':'plan'}/></span><p>{formatPlanEvent(e,language,currency)}</p><small>{e.created_at.slice(0,10)}</small></div>)}</section>}</>}
 {page==='activity'&&<><div className="v3-page-actions"><p>{tr("Recorded movements, across all your accounts.")}</p>{planning&&<button className="v3-secondary" onClick={()=>setPanel({kind:'assign'})}>{tr("Assign or split spending")}</button>}</div><TransactionsPage context={context} revision={revision} onAdd={()=>setModal("transaction")} onEdit={record=>setEdit({kind:"transaction",record})}/></>}
 {page==='plan'&&<><PlanView data={data} onPanel={setPanel} onAdd={()=>setModal('plan')} onEdit={setEdit}/>{planning&&<BudgetPace plan={{name:v3.config.name,period:v3.config.period,start:r.start,end:r.end,target:r.target,funding:r.funding,spent:r.totalSpent,today:data.today,transactions:v3.trendTransactions,occurrences:v3.occurrences,firstRecordedDate:v3.firstRecordedDate,buckets:r.buckets,allocationByTx:r.allocationByTx}} currency={currency} onConfigure={()=>setPanel({kind:'configure'})}/>}<button className="v3-text-button" onClick={()=>navigate('goals')}>{tr("Savings milestones & spare change →")}</button></>}
 {page==='accounts'&&<div className="v3-tabs" role="tablist">{([['balances',tr("Accounts")],['report',tr("Accounts report")]] as const).map(([id,label])=><button role="tab" aria-selected={accountsView===id} className={accountsView===id?'active':''} key={id} onClick={()=>setAccountsView(id)}>{label}</button>)}</div>}
 {page==='accounts'&&accountsView==='report'&&<AccountsReportPage currency={context.currency} revision={revision}/>}
 {page==='accounts'&&accountsView==='balances'&&<AccountsPage context={context} busy={busy} onDefaultExpense={account=>void save("updateDefaultExpenseAccount",{accountId:account.id})} onAdd={()=>setModal('account')} onEdit={record=>setEdit({kind:'account',record})} onSnapshot={setValuation}/>}
 {page==='statistics'&&<><div className="v3-page-actions"><p>{tr("Explore historical activity and spending trends.")}</p></div><StatisticsPage context={context} revision={revision}/></>}
 {page==='settings'&&<><PlanningSettings planning={planning} busy={busy} onEnable={()=>void enablePlanning()} onDisable={()=>void save('updatePlanning',{enabled:false})}/><section className="v3-card"><h2>{tr("Language")}</h2><p>{tr("Choose the language used throughout Remaivo. Your preference follows you across devices.")}</p><LanguageSelect busy={busy} onChange={language=>void save('updateLanguage',{language})}/></section><AppearanceSettings theme={theme} busy={busy} onChange={next=>void save('updateTheme',{theme:next})}/><DataExportCard/><SettingsPage context={context} onCategory={()=>setModal('category')} onGoals={()=>navigate('goals')} onWeek={()=>setModal('week')} onTimezone={()=>setModal('timezone')} onArchive={()=>{setError('');setArchiveOpen(true);}} onEditCategory={record=>setEdit({kind:'category',record})}/></>}
 {page==='goals'&&<><div className="v3-page-actions"><p>{tr("Create a goal bucket in Plan to protect money. These accounts and milestones track your progress.")}</p><button className="v3-secondary" onClick={()=>setPanel({kind:'bucket'})}>{tr("New goal allocation")}</button></div><GoalsPage context={context} onGoal={()=>setModal('goal')} onSpare={()=>setModal('spare')} onSweep={()=>void save('sweepSpare',{})} onEdit={record=>setEdit({kind:'goal',record})} onRecord={setGoalEntry}/></>}
 <footer className="v3-footer"><span>{tr("Remaivo")}</span><span>{data.profile.timezone.replaceAll('_',' ')}  {tr("· Updated through")} {dateLabel(data.today, locale)}</span></footer></div></div>
 {modal&&<FinanceModal name={modal} context={context} busy={busy} error={error} close={()=>{setModal(null);setError('');}} save={saveModal}/>}{edit&&<EditModal target={edit} context={context} busy={busy} error={error} close={()=>{setEdit(null);setError('');}} save={saveModal}/>}{goalEntry&&<GoalEntryModal goal={goalEntry} context={context} busy={busy} error={error} close={()=>{setGoalEntry(null);setError('');}} save={save}/>}{valuation&&<ValuationModal account={valuation} snapshots={data.investmentSnapshots||[]} currency={currency} today={data.today} busy={busy} close={()=>setValuation(null)} save={save}/>}
 {archiveOpen&&<ArchiveManager currency={currency} today={data.today} busy={busy} saveError={error} clearError={()=>setError('')} close={()=>{if(!busy){setArchiveOpen(false);setError('');}}} save={save}/>}
 {panel&&<PlanningPanel panel={panel} data={data} busy={busy} error={error} close={()=>{setPanel(null);setError('');}} save={save}/>}
 </div>;
}

function Empty({title,text}:{title:string;text:string}){
 const { t: tr } = useTranslation();
return <div className="v3-empty"><span>◇</span><h3>{tr(title)}</h3><p>{tr(text)}</p></div>;}
function BucketProgress({bucket,currency}:{bucket:{target_cents:number;spent:number;planned:number;extra:number;deficit:number};currency:string}){
 const { t: tr, locale } = useTranslation();

 const spent=Math.max(0,bucket.spent),upcoming=Math.max(0,bucket.planned),remaining=Math.max(0,bucket.extra);
 const total=Math.max(0,bucket.target_cents,spent+upcoming+remaining);
 const width=(value:number)=>`${total?value/total*100:0}%`;
 const label=`${money(spent,currency, locale)} spent, ${money(upcoming,currency, locale)} upcoming, ${money(remaining,currency, locale)} remaining of ${money(bucket.target_cents,currency, locale)} assigned${bucket.deficit>0?`; ${money(bucket.deficit,currency, locale)} needs cover`:''}`;
 return <span className="v3-bucket-progress" role="img" aria-label={tr(label)}>
  <span className="v3-bucket-progress-spent" style={{width:width(spent)}} aria-hidden="true"/>
  <span className="v3-bucket-progress-upcoming" style={{width:width(upcoming)}} aria-hidden="true"/>
  <span className="v3-bucket-progress-remaining" style={{width:width(remaining)}} aria-hidden="true"/>
 </span>;
}
function OccurrenceList({items,today,currency,onOpen}:{items:Occurrence[];today:string;currency:string;onOpen:(o:Occurrence)=>void}){
 const { t: tr, locale } = useTranslation();
return <div className="v3-occurrence-list">{items.map(o=><button key={o.id} onClick={()=>onOpen(o)}><span className="v3-date-tile"><b>{o.due_date.slice(8)}</b><small>{new Date(o.due_date+'T12:00:00Z').toLocaleDateString(locale,{month:'short',timeZone:'UTC'})}</small></span><span className="v3-occurrence-title"><strong>{o.title}</strong><small>{!['upcoming','partial'].includes(o.status)?o.status+' · ':o.due_date<today?'Overdue · ':o.due_date===today?'Due today · ':''}{o.type==='income'?tr("Expected income"):o.source_kind==='installment'?tr("Installment"):o.auto_post?tr("Scheduled recording"):tr("Awaiting confirmation")}{o.status==='partial'?' · Partially paid':''}</small></span><b className={o.type==='income'?'v3-positive':''}>{o.type==='income'?'+':''}{money(o.amount_cents-o.paid_cents,currency, locale)}</b><span className="v3-row-arrow">›</span></button>)}{!items.length&&<Empty title={tr("Nothing due here")} text={tr("Add a payment plan to see its upcoming dates.")}/>}</div>;}

function PlanView({data,onPanel,onAdd,onEdit}:{data:Snapshot;onPanel:(p:Panel)=>void;onAdd:()=>void;onEdit:(e:EditTarget)=>void}){
 const { t: tr, locale } = useTranslation();

 const planning=data.profile?.planning_enabled!==0;const [tab,setTab]=useState(planning?'allocations':'upcoming');const [horizon,setHorizon]=useState('period');const [status,setStatus]=useState('open');const v=data.v3!;const r=v.result;const m=(n:number)=>money(n,data.profile!.currency, locale);
 const occurrences=v.occurrences.filter(o=>(status==='all'||['upcoming','partial'].includes(o.status))&&(horizon==='all'||o.due_date<r.end));
 return <><div className="v3-tabs" role="tablist">{[['allocations',tr("Allocations")],['upcoming',tr("Upcoming payments")],['sources',tr("Recurring & installments")]].filter(([id])=>planning||id!=='allocations').map(([id,label])=><button role="tab" aria-selected={tab===id} className={tab===id?'active':''} key={id} onClick={()=>setTab(id)}>{tr(label)}</button>)}</div>
 {tab==='allocations'&&<><div className="v3-plan-summary"><div><small>{tr("Period funding")}</small><strong>{m(r.funding)}</strong><button onClick={()=>onPanel({kind:'fund'})}>{tr("Adjust funding")}</button></div><div><small>{tr("Already spent")}</small><strong>{m(r.totalSpent)}</strong></div><div><small>{tr("Still protected")}</small><strong>{m(r.protectedRemaining)}</strong></div><div><small>{tr("Everyday remaining")}</small><strong className={r.available<0?'v3-negative':''}>{m(r.available)}</strong></div></div><section className="v3-card"><div className="v3-section-head"><div><span className="v3-eyebrow">{tr("PURPOSE BEFORE PACE")}</span><h2>{tr("Your allocations")}</h2></div><div className="v3-button-group"><button className="v3-secondary" onClick={()=>onPanel({kind:'move'})}>{tr("Move money")}</button><button className="v3-primary" onClick={()=>onPanel({kind:'bucket'})}><Icon name="plus"/>{tr("New bucket")}</button></div></div><p className="v3-note">{tr("Category spending and linked payments consume the same allocation. They never create a second deduction.")}</p><div className="v3-bucket-progress-legend"><span><i className="v3-bucket-progress-spent" aria-hidden="true"/>{tr("Spent")}</span><span><i className="v3-bucket-progress-upcoming" aria-hidden="true"/>{tr("Upcoming")}</span><span><i className="v3-bucket-progress-remaining" aria-hidden="true"/>{tr("Remaining")}</span></div><div className="v3-bucket-table"><div className="v3-bucket-labels"><span>{tr("Purpose")}</span><span>{tr("Assigned")}</span><span>{tr("Spent")}</span><span>{tr("Upcoming")}</span><span>{tr("Remaining")}</span></div>{r.buckets.map(b=><button className="v3-bucket-row" key={b.id} onClick={()=>onPanel({kind:'bucket',bucket:b})}><span><i className={b.kind==='goal'?'goal':''}>{b.kind==='goal'?'◇':'◫'}</i><span><strong>{b.name}</strong><small>{b.released?tr("Protection released"):b.deficit?`${m(b.deficit)} needs cover`:b.kind==='goal'?tr("Goal allocation"):(data.categories||[]).filter(c=>b.category_ids.includes(c.id)).map(c=>c.name).join(', ')||tr("Manual assignments only")}</small></span></span><b data-label={tr("Assigned")}>{m(b.target_cents)}</b><span data-label={tr("Spent")}>{m(b.spent)}</span><span data-label={tr("Upcoming")}>{m(b.planned)}</span><b data-label={tr("Remaining")} className={b.deficit?'v3-negative':''}>{m(b.extra)}</b><BucketProgress bucket={b} currency={data.profile!.currency}/></button>)}<div className="v3-bucket-row system"><span><i>↻</i><span><strong>{tr("Other commitments")}</strong><small>{tr("Planned payments outside your buckets")}</small></span></span><b data-label={tr("Assigned")}>{m(r.commitmentSpent+r.upcoming)}</b><span data-label={tr("Spent")}>{m(r.commitmentSpent)}</span><span data-label={tr("Upcoming")}>{m(r.upcoming)}</span><b data-label={tr("Remaining")}>{m(r.upcoming)}</b></div><div className="v3-bucket-row system everyday"><span><i>↗</i><span><strong>{tr("Everyday spending")}</strong><small>{tr("The amount used for daily and weekly guidance")}</small></span></span><b data-label={tr("Assigned")}>{m(r.everydayAllocation)}</b><span data-label={tr("Spent")}>{m(r.everydaySpent)}</span><span data-label={tr("Upcoming")}>—</span><b data-label={tr("Remaining")}>{m(r.available)}</b></div></div>{!r.buckets.length&&<Empty title={tr("Make room for what matters")} text={tr("Create a Fuel, Groceries or Savings bucket. Choose a purpose and an amount to protect it in this period.")}/>}</section><section className="v3-card v3-pacing-card"><div><span className="v3-eyebrow">{tr("YOUR RHYTHM")}</span><h2>{tr(v.config.allocation==='adaptive'?tr("Adaptive everyday pacing"):v.config.allocation==='weighted'?tr("Weighted everyday pacing"):tr("Even everyday pacing"))}</h2><p>{v.config.allocation==='adaptive'?tr("Unused everyday money is redistributed across the remaining dates."):tr("Your everyday allocation is divided across the dates in this period.")}  {tr("Covered bucket purchases leave that allowance intact.")}</p></div><button className="v3-secondary" onClick={()=>onPanel({kind:'configure'})}>{tr("Configure plan")}</button></section></>}
 {tab==='upcoming'&&<section className="v3-card"><div className="v3-section-head"><h2>{tr("Every payment, accounted for")}</h2><button className="v3-primary" onClick={onAdd}><Icon name="plus"/>{tr("Add plan")}</button></div><div className="v3-inline-filters"><label>{tr("Horizon")}<select value={horizon} onChange={e=>setHorizon(e.target.value)}><option value="period">{tr("This budget period")}</option><option value="all">{tr("Next 12 months")}</option></select></label><label>{tr("Status")}<select value={status} onChange={e=>setStatus(e.target.value)}><option value="open">{tr("Unpaid")}</option><option value="all">{tr("All occurrences")}</option></select></label><span>{occurrences.length}  {tr("occurrences")}</span></div><OccurrenceList items={occurrences.slice(0,200)} today={data.today} currency={data.profile!.currency} onOpen={o=>onPanel({kind:'payment',occurrence:o})}/>{occurrences.length>200&&<p className="v3-note">{tr("Showing the next 200 occurrences. Narrow the horizon to focus on this period.")}</p>}</section>}
 {tab==='sources'&&<><div className="v3-page-actions"><p>{tr("Manage the schedules behind your upcoming payments.")}</p><button className="v3-primary" onClick={onAdd}><Icon name="plus"/>{tr("Add plan")}</button></div><div className="v3-two-columns"><section className="v3-card"><div className="v3-section-head"><h2>{tr("Recurring plans")}</h2><span className="v3-tag">{data.recurring?.length||0}  {"active"}</span></div>{data.recurring?.map(p=><button className="v3-source-row" key={p.id} onClick={()=>onEdit({kind:'recurring',record:p})}><span><strong>{p.title}</strong><small>{isOncePlan(p)?tr("Once"):repeatLabel(p.frequency,p.interval_count,tr)} · {p.auto_post?tr("Automatic recording"):tr("Confirm each payment")} · {dateLabel(p.next_date, locale)}</small></span><b>{m(p.amount_cents)}</b><span>›</span></button>)}</section><section className="v3-card"><div className="v3-section-head"><h2>{tr("Pay later")}</h2><span className="v3-tag">{data.installmentPlans?.length||0}  {"active"}</span></div>{data.installmentPlans?.map(p=><button className="v3-source-row" key={p.id} onClick={()=>onEdit({kind:'installment',record:p})}><span><strong>{p.title}</strong><small>{m(p.paid_cents)}  {tr("of")} {m(p.total_cents)}  {tr("paid ·")} {p.installment_count}  {tr("payments")}</small><span className="v3-mini-progress"><i style={{width:`${Math.min(100,p.paid_cents/p.total_cents*100)}%`}}/></span></span><b>{m(p.total_cents-p.paid_cents)}  {tr("left")}</b><span>›</span></button>)}{!data.installmentPlans?.length&&<Empty title={tr("No active installments")} text={tr("A single deferred purchase or a split purchase will appear here.")}/>}</section></div></>}
 </>;
}

function Dialog({title,subtitle,close,children,currency}:{title:string;subtitle?:string;close:()=>void;children:ReactNode;currency:string}){
 const { t: tr } = useTranslation();

 return <div className="v3-dialog-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)close();}}><DialogFrame className="v3-dialog" currency={currency} close={close} labelledBy="v3-dialog-title"><DialogHeading id="v3-dialog-title" icon="plan" title={tr(title)} copy={tr(subtitle)}/>{children}</DialogFrame></div>;
}

function PlanningPanel({panel,data,busy,error,close,save}:{panel:Panel;data:Snapshot;busy:boolean;error:string;close:()=>void;save:(a:string,p:Record<string,unknown>)=>Promise<boolean>}){
 const { t: tr, locale } = useTranslation();

 const v=data.v3!;const r=v.result;const config=v.config;const m=(n:number)=>money(n,data.profile!.currency, locale);const [confirmSkip,setConfirmSkip]=useState(false);const [paidAmount,setPaidAmount]=useState('');const [period,setPeriod]=useState(config.period);const [allocation,setAllocation]=useState(config.allocation);const [kind,setKind]=useState(panel.kind==='bucket'?panel.bucket?.kind||'protected':'protected');const [selectedTx,setSelectedTx]=useState(v.transactions.find(t=>['expense','saving','investment','installment_payment'].includes(t.type)&&t.counts_monthly!==0)?.id||'');const [paymentAction,setPaymentAction]=useState('record');
 const submit=(action:string,extra:Record<string,unknown>={})=>async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=new FormData(e.currentTarget);const values=Object.fromEntries(form);const payload:Record<string,unknown>={...values,...extra};if(action==='v3Bucket')payload.categoryIds=form.getAll('categoryIds').map(String);if(action==='v3Settle')payload.close=form.get('close')==='on';if(action==='v3Configure'){Object.assign(payload,{period,allocation,weights:Array.from({length:7},(_,i)=>Number(values['weight'+i]||config.weights[i]))});}if(action==='v3Assign'){Object.assign(payload,{transactionId:selectedTx,splits:[{bucketId:String(values.bucket1||''),amount:values.amount1},{bucketId:String(values.bucket2||''),amount:values.amount2}].filter(s=>s.bucketId&&Number(s.amount)>0)});}if(await save(action,payload))close();};
 const button=(label=tr("Save changes"))=><DialogSubmit busy={busy} label={tr(label)}/>;
 const errorBox=error?<div className="v3-alert" role="alert">{tr(error)}</div>:null;
 if(panel.kind==='explain'){
 const view=panel.view;const g=view==='daily'?r.daily:r.weekly;const title=view==='available'?tr("Where everyday money comes from"):view==='cash'?'Your spending-account cash':view==='daily'?tr("Today’s allowance, explained"):tr("This week’s allowance, explained");
 return <Dialog currency={data.profile!.currency} title={tr(title)} close={close}><div className="v3-equation">{view==='available'?<><Equation label={tr("Funded for this period")} amount={r.funding} currency={data.profile!.currency}/><Equation label={tr("Posted spending")} amount={-r.totalSpent} currency={data.profile!.currency}/><Equation label={tr("Unpaid plans outside buckets")} amount={-r.upcoming} currency={data.profile!.currency}/>{r.buckets.filter(b=>b.remaining).map(b=><Equation key={b.id} label={b.name+' still protected'} amount={-b.remaining} currency={data.profile!.currency}/>)}<Equation label={tr("Everyday remaining")} amount={r.available} currency={data.profile!.currency} total/></>:view==='cash'?<>{(data.accounts||[]).filter(a=>!a.archived&&a.include_spendable&&a.type!=='investment').map(a=><Equation key={a.id} label={a.name} amount={a.balance_cents} currency={data.profile!.currency}/>)}<Equation label={tr("Spending-account cash")} amount={r.spendable} currency={data.profile!.currency} total/></>:<><Equation label={config.allocation==='adaptive'?tr("Allocation from the remaining everyday pool"):tr("Calendar allocation")} amount={g.base} currency={data.profile!.currency}/><Equation label={tr("Carry from earlier dates")} amount={g.carry} currency={data.profile!.currency}/><Equation label={tr("Everyday spending in this window")} amount={-g.spent} currency={data.profile!.currency}/><Equation label={tr("Remaining allowance")} amount={g.remaining} currency={data.profile!.currency} total/></>}</div><p className="v3-note">{view==='cash'?tr("Protected allocations do not move money between accounts. They describe its purpose."):view==='available'?tr("A covered payment replaces the unpaid amount or consumes its bucket. It is counted once."):tr("Bucket spending and committed payments are covered separately. Allowance is a pacing guide; review upcoming payments and your plan for cash timing. Weeks stop at the current period boundary.")}</p></Dialog>;
 }
 if(panel.kind==='configure')return <Dialog currency={data.profile!.currency} title={tr("Make the plan yours")} subtitle={tr("Settings apply to this open period. Existing historical periods retain their saved configuration.")} close={close}>{errorBox}<form onSubmit={submit('v3Configure')}><Field label={tr("Plan name")}><input name="name" defaultValue={config.name} required maxLength={80}/></Field><div className="v3-form-grid"><Field label={tr("Spending target")}><input name="target" type="number" min="0" step="0.01" defaultValue={config.target/100} required/></Field><Field label={tr("Budget period")}><select value={period} onChange={e=>setPeriod(e.target.value as typeof period)}><option value="monthly">{tr("Calendar month")}</option><option value="weekly">{tr("Every 7 days")}</option><option value="fortnightly">{tr("Every 14 days")}</option><option value="payday">{tr("Payday to payday")}</option><option value="custom">{tr("Custom dates")}</option></select></Field></div>{period==='payday'&&<Field label={tr("Monthly payday")}><input name="payday" type="number" min="1" max="31" defaultValue={config.payday}/></Field>}<div className="v3-form-grid"><Field label={period==='custom'?tr("Start date"):tr("Cycle anchor date")}><input name="anchor" type="date" defaultValue={config.anchor} required/></Field><Field label={tr("Custom end date (exclusive)")}><input name="end" type="date" defaultValue={config.end} required disabled={period!=='custom'}/></Field></div><Field label={tr("Everyday pacing")}><select value={allocation} onChange={e=>setAllocation(e.target.value as typeof allocation)}><option value="adaptive">{tr("Adaptive · redistribute what remains")}</option><option value="even">{tr("Even · equal calendar slices")}</option><option value="weighted">{tr("Weighted · set your weekday rhythm")}</option></select></Field>{allocation==='weighted'&&<div className="v3-weights">{[tr("Sun"),tr("Mon"),tr("Tue"),tr("Wed"),tr("Thu"),tr("Fri"),tr("Sat")].map((d,i)=><Field key={d} label={d}><input name={'weight'+i} type="number" min="0.1" max="10" step="0.1" defaultValue={config.weights[i]}/></Field>)}</div>}{allocation!=='adaptive'&&<div className="v3-form-grid"><Field label={tr("Carry inside this period")}><select name="carry" defaultValue={config.carry}><option value="none">{tr("None")}</option><option value="positive">{tr("Positive only")}</option><option value="signed">{tr("Surplus and deficit")}</option><option value="capped">{tr("Capped positive")}</option></select></Field><Field label={tr("Carry cap")}><input name="carryCap" type="number" min="0" step="0.01" defaultValue={config.carryCap/100}/></Field></div>}<input type="hidden" name="end" value={config.end} disabled={period==='custom'}/><input type="hidden" name="weekStart" value={data.profile!.week_start}/><p className="v3-note">{tr("A target is a limit, not a deposit. Adjust funding separately to assign recorded cash. Changing the period opens that period using its own funding and bucket records.")}</p>{button(tr("Save plan"))}</form><div className="v3-dialog-actions"><button type="button" disabled={busy} onClick={async()=>{if(await save('updatePlanning',{enabled:false}))close();}}>{tr("Turn off planning")}</button></div></Dialog>;
 if(panel.kind==='fund')return <Dialog currency={data.profile!.currency} title={tr("Fund this period")} subtitle={tr("Assign recorded money to the plan. This does not create income or move account balances.")} close={close}>{errorBox}<form onSubmit={submit('v3Fund')}><div className="v3-equation"><Equation label={tr("Spending-account cash now")} amount={r.spendable} currency={data.profile!.currency}/><Equation label={tr("Already spent in this period")} amount={r.totalSpent} currency={data.profile!.currency}/><Equation label={tr("Maximum total period funding")} amount={Math.max(0,r.spendable+r.totalSpent)} currency={data.profile!.currency} total/></div><Field label={tr("Total funding, including money already spent")}><input name="amount" type="number" min="0" max={Math.max(0,r.spendable+r.totalSpent)/100} step="0.01" defaultValue={r.funding/100} required/></Field><p className="v3-note">{tr("Expected income is not available for funding until recorded. Funding is capped by the current spending-account cash and actual spending in this period.")}</p>{button(tr("Update funding"))}</form></Dialog>;
 if(panel.kind==='bucket'){const b=panel.bucket;const expenseCategories=(data.categories||[]).filter(c=>c.kind==='expense'&&(!c.archived||b?.category_ids.includes(c.id)));return <Dialog currency={data.profile!.currency} title={b?'Edit '+b.name:'Give money a purpose'} subtitle={tr("An assignment protects money; purchases in its matching categories consume it. Current-period history is included when matching.")} close={close}>{errorBox}<form onSubmit={submit('v3Bucket',{id:b?.id,kind})}><Field label={tr("Name")}><input name="name" defaultValue={b?.name||''} placeholder={tr("Fuel, groceries, emergency fund…")} required maxLength={100}/></Field><div className="v3-form-grid"><Field label={tr("Purpose")}><select value={kind} onChange={e=>setKind(e.target.value as typeof kind)}><option value="protected">{tr("Protected spending")}</option><option value="goal">{tr("Goal allocation")}</option></select></Field><Field label={tr("Assigned each period")}><input name="target" type="number" min="0" step="0.01" defaultValue={(b?.target_cents||0)/100} required/></Field></div><fieldset className="v3-category-picker"><legend>{tr("Match expense categories")}</legend>{expenseCategories.length>0&&<div className="check-stack">{expenseCategories.map(c=>{const owner=r.buckets.find(x=>x.id!==b?.id&&x.category_ids.includes(c.id));return <label key={c.id}><input type="checkbox" name="categoryIds" value={c.id} defaultChecked={b?.category_ids.includes(c.id)} disabled={Boolean(owner)}/><span>{c.name}{owner?<small>{tr("Already in")} {owner.name}</small>:c.archived?<small>{tr("Archived category")}</small>:null}</span></label>;})}</div>}<small>{tr("Purchases in any selected category use this bucket. Leave all unchecked to assign spending manually.")}</small></fieldset>{kind==='goal'&&<Field label={tr("Match transfers into account")}><select name="destinationId" defaultValue={b?.destination_id||''}><option value="">{tr("No linked destination")}</option>{data.accounts?.filter(a=>!a.archived).map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></Field>}<div className="v3-form-grid"><Field label={tr("Unused amount next period")}><select name="rollover" defaultValue={b?.rollover||'none'}><option value="none">{tr("Reset to target")}</option><option value="positive">{tr("Add positive remainder")}</option><option value="signed">{tr("Carry surplus and deficit")}</option><option value="capped">{tr("Capped positive remainder")}</option></select></Field><Field label={tr("Rollover cap")}><input name="rolloverCap" type="number" min="0" step="0.01" defaultValue={(b?.rollover_cap||0)/100}/></Field></div><p className="v3-note">{tr("Rollover changes the next period’s allocation target; it does not create cash. New allocations reduce everyday money. Scheduled payments in the same category are covered inside the target.")}</p>{button(b?tr("Save bucket"):tr("Create bucket"))}</form>{b&&<div className="v3-dialog-actions"><button disabled={busy} onClick={async()=>{if(await save(b.released?'v3Reopen':'v3Release',{id:b.id}))close();}}>{b.released?tr("Restore this period’s protection"):tr("Release unused money this period")}</button><button disabled={busy} onClick={async()=>{if(await save('v3ArchiveBucket',{id:b.id}))close();}}>{tr("Stop repeating this bucket")}</button></div>}</Dialog>;}
 if(panel.kind==='move')return <Dialog currency={data.profile!.currency} title={tr("Move an allocation")} subtitle={tr("Reassign unused money for this period. Account balances and the next period’s target stay unchanged.")} close={close}>{errorBox}<form onSubmit={submit('v3Move')}><div className="allocation-accounts">{['from','to'].map((name,i)=><Field key={name} label={i?tr("To"):tr("From")}><select name={name} defaultValue={i?r.buckets[0]?.id:'everyday'}><option value="everyday">{tr("Everyday ·")} {m(r.available)}</option>{r.buckets.map(b=><option key={b.id} value={b.id}>{b.name} · {m(b.extra)}  {tr("unused")}</option>)}</select></Field>)}</div><Field label={tr("Amount")}><input name="amount" type="number" min="0.01" step="0.01" required/></Field>{button(tr("Move allocation"))}</form></Dialog>;
 if(panel.kind==='payment'){const o=panel.occurrence;const left=o.amount_cents-o.paid_cents;const flexible=o.source_kind==='recurring';const typed=paidAmount===''?left:Math.round(Number(paidAmount)*100);const open=['upcoming','partial'].includes(o.status);return <Dialog currency={data.profile!.currency} title={o.title} subtitle={`${dateLabel(o.due_date, locale)} · ${o.type==='income'?tr("Expected income"):o.source_kind==='installment'?tr("Installment"):tr("Recurring payment")} · ${o.status}`} close={close}>{errorBox}<div className="v3-payment-total">{m(left)}<small>{m(o.paid_cents)}  {tr("recorded of")} {m(o.amount_cents)}</small></div>{open&&<><div className="v3-tabs">{[['record',tr("Record payment")],['match',tr("Match activity")],['reschedule',tr("Reschedule")]].map(([k,l])=><button key={k} className={paymentAction===k?'active':''} onClick={()=>setPaymentAction(k)}>{l}</button>)}</div>{paymentAction==='reschedule'?<form onSubmit={submit('v3Reschedule',{id:o.id})}><Field label={tr("New due date")}><input name="date" type="date" min={data.today} defaultValue={o.due_date<data.today?data.today:o.due_date} required/></Field>{button(tr("Reschedule"))}</form>:<form onSubmit={submit('v3Settle',{id:o.id})}><div className="v3-form-grid"><Field label={tr("Actual payment date")}><input name="date" type="date" max={data.today} defaultValue={data.today} required/></Field><Field label={tr("Amount recorded")}><input name="amount" type="number" min="0.01" max={flexible?undefined:left/100} step="0.01" defaultValue={left/100} onChange={e=>setPaidAmount(e.target.value)} required/></Field></div>{flexible&&typed>0&&typed<left&&<label className="v3-check v3-settle-close"><input type="checkbox" name="close" defaultChecked/><span>{tr("This payment is done")}<small>{m(left-typed)} {tr("left unpaid is released. Untick if more is still to come.")}</small></span></label>}{flexible&&typed>left&&<p className="v3-note">{m(typed)} {tr("is more than the")} {m(left)} {tr("planned. The full amount is recorded and the payment is closed.")}</p>}{paymentAction==='match'&&<Field label={tr("Existing unlinked transaction")}><select name="matchId" required defaultValue=""><option value="" disabled>{tr("Choose matching activity")}</option>{v.transactions.filter(t=>t.type===o.type&&t.account_id===o.account_id&&!t.recurring_plan_id&&!t.installment_plan_id).map(t=><option key={t.id} value={t.id}>{t.date} · {t.description} · {m(t.amount_cents)}</option>)}</select></Field>}<p className="v3-note">{paymentAction==='match'?tr("Matching links an existing transaction without moving money again. Its amount must match the amount above."):tr("Recording updates the account and settles this occurrence. Partial payments keep the unpaid remainder protected.")}</p>{button(paymentAction==='match'?tr("Match transaction"):tr("Record payment"))}</form>}{flexible&&o.paid_cents>0&&<div className="v3-dialog-actions"><button type="button" disabled={busy} onClick={async()=>{if(await save('v3Close',{id:o.id}))close();}}>{tr("Mark as done")} · {tr("release")} {m(left)}</button></div>}{o.source_kind==='recurring'&&!o.paid_cents&&(confirmSkip?<div className="v3-skip-confirm"><p><strong>{tr("Skip this payment?")}</strong><small>{dateLabel(o.due_date, locale)} · {m(left)}. {tr("A skipped payment can't be brought back. Later payments stay as planned.")}</small></p><div><button type="button" disabled={busy} onClick={()=>setConfirmSkip(false)}>{tr("Keep it")}</button><button type="button" className="v3-danger" disabled={busy} onClick={async()=>{if(await save('v3Skip',{id:o.id}))close();}}>{tr("Yes, skip it")}</button></div></div>:<div className="v3-dialog-actions"><button type="button" disabled={busy} onClick={()=>setConfirmSkip(true)}>{tr("Skip this occurrence")}</button></div>)}</>}</Dialog>;}
 const tx=v.transactions.find(t=>t.id===selectedTx);return <Dialog currency={data.profile!.currency} title={tr("Assign or split spending")} subtitle={tr("Explicit assignments take priority over category matching. Any remainder follows its normal everyday or commitment classification.")} close={close}>{errorBox}<form onSubmit={submit('v3Assign')}><Field label={tr("Transaction in this period")}><select value={selectedTx} onChange={e=>setSelectedTx(e.target.value)} required>{v.transactions.filter(t=>['expense','saving','investment','installment_payment'].includes(t.type)&&t.counts_monthly!==0).map(t=><option key={t.id} value={t.id}>{t.date} · {t.description} · {m(t.amount_cents)}</option>)}</select></Field>{tx&&<p className="v3-note">{tr("Total")} {m(tx.amount_cents)}{tr(". Leave both assignments empty to restore automatic matching.")}</p>}{[1,2].map(i=><div className="v3-form-grid" key={i}><Field label={'Bucket '+i}><select name={'bucket'+i} defaultValue=""><option value="">{tr("Automatic remainder")}</option>{r.buckets.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></Field><Field label={tr("Amount")}><input name={'amount'+i} type="number" min="0" step="0.01" max={(tx?.amount_cents||0)/100} placeholder="0.00"/></Field></div>)}{button(tr("Save assignments"))}</form></Dialog>;
}
// Without a plan, the Overview leads with this month's money in and out,
// compared with the same days of last month.
type MonthSummary=NonNullable<Snapshot['month']>;
function MonthCard({month,currency,onInsights}:{month:MonthSummary;currency:string;onInsights:()=>void}){
 const { t: tr, locale } = useTranslation();
 const m=(n:number)=>money(n,currency,locale);const net=month.income-month.spending;const previousNet=month.previousIncome-month.previousSpending;
 const change=(now:number,before:number,goodWhenUp:boolean)=>{const diff=now-before;if(!diff)return <small>{tr("Same as last month so far")}</small>;return <small className={(diff>0)===goodWhenUp?'v3-positive':'v3-negative'}>{diff>0?'+':'−'}{m(Math.abs(diff))} {tr("vs last month so far")}</small>;};
 return <section className="v3-card v3-month-card"><div className="v3-hero-top"><span className="v3-eyebrow">{tr("This month")} · {dateLabel(month.start,locale)} — {tr("today")}</span><button onClick={onInsights}>{tr("Open Insights")}</button></div>
  <strong className={`v3-month-net ${net<0?'negative':''}`}>{net<0?'−':'+'}{m(Math.abs(net))}</strong><p>{tr("Money in minus money out this month.")}</p>
  <div className="v3-month-grid"><div><span>{tr("Money in")}</span><b>{m(month.income)}</b>{change(month.income,month.previousIncome,true)}</div><div><span>{tr("Money out")}</span><b>{m(month.spending)}</b>{change(month.spending,month.previousSpending,false)}</div><div><span>{tr("Net")}</span><b>{m(net)}</b>{change(net,previousNet,true)}</div></div></section>;
}

function PlanningSettings({planning,busy,onEnable,onDisable}:{planning:boolean;busy:boolean;onEnable:()=>void;onDisable:()=>void}){
 const { t: tr } = useTranslation();const [confirming,setConfirming]=useState(false);
 return <section className="v3-card v3-planning-settings"><h2>{tr("Spending plan")}</h2><p>{tr(planning?"Planning is on. Remaivo paces your everyday spending, protects bucket money and holds money for upcoming bills.":"Planning is off. Remaivo tracks money in and out, and still lists upcoming bills as a reminder.")}</p>
  {planning?(confirming?<div className="v3-skip-confirm"><p><strong>{tr("Turn off planning?")}</strong><small>{tr("Your plan, buckets and schedules are kept. Turning planning back on restores them.")}</small></p><div><button type="button" disabled={busy} onClick={()=>setConfirming(false)}>{tr("Keep planning")}</button><button type="button" className="v3-danger" disabled={busy} onClick={()=>{setConfirming(false);onDisable();}}>{tr("Turn off")}</button></div></div>:<button className="v3-secondary" disabled={busy} onClick={()=>setConfirming(true)}>{tr("Turn off planning")}</button>):<button className="v3-primary" disabled={busy} onClick={onEnable}>{tr("Turn on planning")}</button>}
 </section>;
}

function Equation({label,amount,currency,total=false}:{label:string;amount:number;currency:string;total?:boolean}){
 const { t: tr, locale } = useTranslation();
return <div className={total?'total':''}><span>{tr(label)}</span><strong>{money(amount,currency, locale)}</strong></div>;}

export function RemaivoV3(props:{displayName:string;email:string;signOutHref:string}) { return <LanguageProvider><RemaivoWorkspace {...props}/></LanguageProvider>; }
